select count(l.resource_id) as count,l.create_time,r.role_group as roleGroup from cr_eval_task_log l left join cr_eval_train_task t on t.resource_id = l.task_id left join cr_eval_role r on r.resource_id = t.role_id where l.eval_template_id = #{evalTemplateId} and l.action_code in
#{item}
group by l.create_time,t.role_id
